import Banner from "./Bannner";
import ContactFooter from "./ContactFooter";
import HTMLRenderer from "./HtmlRenderer"

import { useEffect, useState } from "react";
import glv from "../utils/getLocalizedValue"
import getNews from "../utils/news/getNews";

function NewsContainer({ title, content, date, imgSrc }) {
  let [isOpen, setIsOpen] = useState();

  return (
    <>
      <article className="font-pretendard flex flex-col w-full sm:w-[70rem] sm:max-w-full py-5 px-5 my-4 first:mt-0 last:mb-0 shadow-[rgba(0,0,15,0.1)_0px_5px_4px_0px] bg-brand-silicon-white">
        <header className="flex">
          <div
            className={`sm:flex hidden transition-[width] duration-500 ${isOpen ? "w-[20rem]" : "w-[10rem]"
              }`}
          >
            <img src={imgSrc} alt="" className="object-cover w-auto h-auto" />
          </div>
          <div className="flex flex-col justify-center sm:ms-10 ms-0 w-[60rem]">
            <h2 className="flex h-full sm:text-3xl text-xl font-black w-full items-center">
              <HTMLRenderer htmlString={title && title} />
            </h2>
            <time className="flex font-[700]">{date && date}</time>
          </div>
          <div className="flex ms-auto h-full min-w-[2.5rem] max-w-[2.5rem] relative">
            <button
              onClick={() => {
                setIsOpen(!isOpen);
              }}
              className={`absolute sm:top-[2rem] top-[1rem] transition-transform duration-500 transform ${isOpen ? "scale-y-[-1]" : ""
                }`}
            >
              <img
                src={require("../assets/icon/expand.png")}
                alt=""
                className="w-[2.5rem]"
              />
            </button>
          </div>
        </header>
        <section
          className={`font-[300] main-content text-lg leading-10 mt-5 transition-[max-height] duration-500 overflow-y-scroll ${isOpen
              ? "max-h-full pointer-events-auto"
              : "max-h-0 pointer-events-none"
            }`}
        >
          <HTMLRenderer htmlString={content && content} />
        </section>
      </article>
    </>
  );
}

